const inp = $input.first().json;

const question = String(inp.question ?? '').trim();
const query    = String(inp.query ?? '').trim();

// `question` is the raw user message, wired straight from the chat trigger, so it
// is the one input the model cannot shape. `query` is the agent's own
// reformulation and is only ever a fallback — decomposing the agent's already
// collapsed phrasing is what this workflow exists to stop relying on.
const subject = question || query;
if (!subject) throw new Error('wf-step-retrieve-multi called with neither question nor query');

const payload = {
  model: 'hf.co/unsloth/Qwen3.8-27B-GGUF:UD-Q4_K_M',
  messages: [{ role: 'user', content: "You split a homebrewing question into the separate things it asks for.\n\nReturn one short search query per distinct topic, in the order they were asked. Each query must be four to six words, name its own topic, and stand alone without the others.\n\nRules:\n- A question that asks for one thing returns exactly ONE query. Do not invent extra topics.\n- Never return more than three.\n- Repeat the beer style or ingredient name in queries about recipes, water, yeast or grain bills. Those live in style-specific passages.\n- Off-flavours, faults and \"what should I watch for\" are their own topic, and are the ONE exception: do NOT attach a style name to them. Fault descriptions are written style-agnostically, so naming the style retrieves the style guide instead of the fault list. Use plain wording like \"common beer faults and off-flavors\".\n- Do not answer the question. Return queries only.\n\nExample question: I am brewing an Irish stout. What water profile should I target, which yeast, and what off-flavour should I watch for?\nExample queries: [\"Irish stout water profile\", \"Irish stout yeast strain\", \"common beer faults and off-flavors\"]\n\nExample question: What causes diacetyl and how do I get rid of it?\nExample queries: [\"diacetyl cause and prevention\"]\n\nQuestion: " + subject }],
  // Splitting a question has one right answer; sampling only adds variance.
  options: { temperature: 0, num_predict: 200 },
  stream: false,
  // `think: false` is load-bearing, not a tweak. The model otherwise spends the
  // whole budget in its `thinking` field and returns empty content — the §2.6
  // quirk, reproduced here every time. `measured` on gemma4:12b-it-q8_0: 1.0 s with it,
  // 11.1 s without. Re-confirmed in wf-step-llm's compose step 2026-09-15.
  think: false,
  // Structured output: the parse in `Plan parts` must not depend on the model
  // deciding to emit clean JSON.
  format: {
    type: 'object',
    properties: { queries: { type: 'array', items: { type: 'string' } } },
    required: ['queries'],
  },
};

return [{ json: { payload, subject } }];

const inp = $('When Executed by Another Workflow').first().json;

// Ollama's /api/chat puts the structured answer in message.content as a string.
let parts = [];
try {
  const parsed = JSON.parse($json.message?.content ?? '');
  if (Array.isArray(parsed.queries)) parts = parsed.queries;
} catch (e) {
  // Deliberately swallowed: a malformed split must degrade to a single search,
  // not fail the tool. The fallback below is the whole recovery path.
}

parts = parts.map(s => String(s ?? '').trim()).filter(Boolean).slice(0, 3);

if (!parts.length) {
  const fb = String(inp.query ?? inp.question ?? '').trim();
  if (!fb) throw new Error('wf-step-retrieve-multi: decomposition empty and no fallback query');
  parts = [fb];
}

const k = Number(inp.top_k);
const top_k = Number.isFinite(k) && k > 0 ? Math.min(Math.round(k), 8) : 8;
const session_id = String(inp.session_id ?? '').trim();

// One item per part. `Search part` runs once per item, so this is the fan-out:
// the number of searches is fixed here, not left to the agent to comply with.
return parts.map(q => ({ json: { query: q, top_k, mode: 'rows', session_id } }));

const planned = $('Plan parts').all().map(i => i.json.query);

// One input item per part, each carrying that part's rows. Deduped by chunk_id:
// parts of one question overlap (an Irish stout recipe chunk answers both the
// water and the yeast part), and the same passage listed twice under two labels
// is what invites a miscitation.
const seen = new Set();
const rows = [];
for (const item of $input.all()) {
  for (const r of (item.json.rows ?? [])) {
    if (seen.has(r.chunk_id)) continue;
    seen.add(r.chunk_id);
    rows.push(r);
  }
}

// ⛔ This merge, not wf-step-retrieve's `text` shape, is where the model's text
// is actually built: every live caller asks for `rows`, so the web passages have
// to be assembled HERE too or they never reach the model. Measured 2026-09-15 --
// the Lotus question refused while gap_terms={lotus} and the web arm had already
// returned, because the passages stopped at a shape nothing reads.
const webSeen = new Set();
const web = [];
const gapSeen = new Set();
for (const item of $input.all()) {
  for (const w of (item.json.web ?? [])) {
    if (!w || webSeen.has(w.url)) continue;     // one passage per source
    webSeen.add(w.url);
    web.push(w);
  }
  for (const g of (item.json.gap ?? [])) gapSeen.add(g);
}
const gap = [...gapSeen];

const asked = planned.map(q => `"${q}"`).join(', ');

// Text shape — for the model. ONE item, ONE key. Mirrors `Return rows` in
// wf-step-retrieve; the agent must not be able to tell which tool it called.
if (!rows.length && !web.length) {
  return [{ json: { response: `No passages in the library matched ${asked}.` } }];
}

const libraryBlock = rows.length
  ? `${rows.length} passages from the library, searched as ${asked}:\n\n` +
    rows.map((x, n) =>
      `[S${n + 1}] ${x.doc_title} · ${x.heading}${x.page ? ` · p.${x.page}` : ''}\n${x.text}`
    ).join('\n\n')
  : `No passages in the library matched ${asked}.`;

if (!web.length) {
  return [{ json: { response: libraryBlock } }];
}

// ⛔ [W..] is a DIFFERENT marker from [S..] on purpose, and the sentence below is
// an instruction the model reads. Web passages carry none of the library's
// editorial vetting and must never be presented as though they do.
const webBlock = web.map((x, n) =>
  `[W${n + 1}] ${x.url}${x.heading ? ` · ${x.heading}` : ''}\n${x.text}`
).join('\n\n');

const gapNote = gap.length
  ? `Your library has never seen ${gap.map(t => `"${t}"`).join(', ')}, so the passages below came from the web.`
  : 'The passages below came from the web, not your library.';

return [{ json: {
  response: `${libraryBlock}\n\n---\n${gapNote}\n` +
    `Answer the question using them. Cite them as [W1], [W2] — NOT as [S1] — and ` +
    `say plainly that this part is from the web and is not in the library.\n\n${webBlock}`,
}}];
